CHOICES={n:0 for n,t in enumerate(TASKS,1) if isinstance(t[2],list)}
UNITS={1:'Ω',5:'Ω',14:'Ω'}
FIGURES={1:'Nel primo circuito i resistori da2 e3 Ω sono davvero in serie: il nodo intermedio non ha derivazioni. Il secondo schema è il caso autonomo del bypass, con2 e4 Ω: il filo collega soltanto i capi del4 Ω e lascia il2 Ω attivo. Le barre finali confrontano totali5 e8 Ω, media13/2 Ω.',6:'Nel secondo pannello il filo ideale unisce soltanto i nodi ai capi del4 Ω. La tensione su quel resistore è zero; il2 Ω resta fra i morsetti esterni. Non si applica più la vecchia somma2+4 dopo il collegamento del filo.',12:'Le barre finali hanno origine e scala comuni:5 e8 Ω, media13/2 Ω. Le due coppie sono prove distinte, non quattro resistori collegati insieme. Le medie dei due addendi5/2 e4 Ω danno qui lo stesso totale per linearità.'}
def assemble(repo,source_ref):
 return assemble_family(repo,source_ref,'two-series-resistors',TASKS,CHOICES,UNITS,'two-series-resistors-progressive.svg',FIGURES,20600,unit='u6',course='C4',source_path='packages/engine/lessonos/study/content/physics-semestre-2026-bank/questions/U6-02.json',skill='C4-L06',prerequisites=['C1-L001','C1-L002','C4-L03','C4-L05','C4-L06'],section='Nodi e resistenze in serie',coverage=['Corrente comune e somma delle cadute','Topologia del bypass ideale','Inverse con residuo positivo, medie e tarature'])
if __name__=='__main__':write_family(assemble,'two-series-resistors-206')
